  );
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateEntityField' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateEntityField"(p_data := jsonb_build_object(
    'JSONTypeDefinition', p_JSONTypeDefinition_d846ac842c18,
    'ID', p_ID_d846ac842c18
  ));
  ELSE
    PERFORM __mj."spUpdateEntityField"(p_JSONTypeDefinition := p_JSONTypeDefinition_d846ac842c18, p_ID := p_ID_d846ac842c18);
  END IF;
