    END IF;
  ELSE
    IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateScheduledJob' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
      PERFORM __mj."spUpdateScheduledJob"(p_data := jsonb_build_object(
