          duration: 750, // Initial animation\n          onComplete: () => {\n            // Disable animations after initial render to prevent re-animation on clicks\n            if (chartInstanceRef.current) {\n              chartInstanceRef.current.options.animation = false;\n            }\n          }\n        },\n        interaction: {\n          mode: ''nearest'',\n          intersect: true\n        },\n        hover: {\n          mode: ''nearest'',\n          intersect: true\n        },\n        elements: {\n          bar: {\n            hoverBorderWidth: 0,\n            borderSkipped: false\n          },\n          arc: {\n            hoverOffset: 6,\n            hoverBorderWidth: 2,\n            hoverBorderColor: surfaceColor\n          },\n          line: {\n            hoverBorderWidth: 4\n          },\n          point: {\n            hoverRadius: 7,\n            hoverBorderWidth: 2,\n            hoverBackgroundColor: surfaceColor\n          }\n        },\n        onHover: (event, activeElements) => {\n          // Change cursor to pointer when hovering over data points\n          event.native.target.style.cursor = activeElements.length > 0 ? ''pointer'' : ''default'';\n        },\n        onClick: (_event, elements) => {\n          if (elements && elements.length > 0 && onDataPointClickRef.current) {\n            const { data, processData } = latestDataRef.current;\n            const clickedElement = elements[0];\n            const categoryIndex = clickedElement.index;\n            const datasetIndex = clickedElement.datasetIndex;\n            const isStacked = stackBy && processData.datasets && processData.datasets.length > 0;\n\n            let clickedData;\n            let clickedLabel;\n            let clickedRecords;\n            let clickedValue;\n\n            if (isStacked) {\n              // STACKED MODE: Filter by both category and stack value\n              const category = processData.categories[categoryIndex];\n              const stackValu