-- Save MJ: Remote Operations (core SP call only)
DO $mj$
DECLARE
  p_Description_b00a8cc8927b TEXT;
  p_InputTypeDefinition_b00a8cc8927b TEXT;
  p_OutputTypeDefinition_b00a8cc8927b TEXT;
  p_ID_b00a8cc8927b UUID;
BEGIN
  p_Description_b00a8cc8927b := 'Trains a predictive model from an ML Training Pipeline under the pipeline''s Prediction Unit and Evaluation Protocol: freezes a Training Snapshot, carves the locked holdout by date, selects on inner folds, fits the baselines and stores the three-outcome gate decision with its reason on the training run. Outputs the run''s gate outcome and reason, the snapshot and protocol, the model id (none under no-signal), the test-set scores and whether one feature dominates the predictions (possible target leakage).';
  p_InputTypeDefinition_b00a8cc8927b := '/** A point-in-time assembly strategy, as `PredictiveStudio.TrainModel` accepted it before Prediction Units (see {@link RetiredTrainModelInputs}). */
export interface PredictiveStudioTrainAsOf {
    /** How to anchor feature assembly in time: no anchoring, a column on the row, or an offset before the label event. */
    Mode: ''none'' | ''column'' | ''offset'';
    /** Column carrying the as-of timestamp (when `Mode` is `column`). */
    Column?: string;
    /** Days before the label event to assemble features (when `Mode` is `offset`). */
    OffsetDays?: number;
}

/** Input for `PredictiveStudio.TrainModel`. The pipeline''s Prediction Unit and Evaluation Protocol decide everything else. */
export interface PredictiveStudioTrainModelInput {
    /** Id of the `MJ: ML Training Pipelines` row to train. */
    pipelineId: string;
    /** Optional `MJ: Experiment Session Iterations` id this run belongs to (NULL for a one-off standalone train). */
    experimentSessionIterationId?: string;
    /** Sidecar version string recorded in the model lineage for provenance. */
    sidecarVersion?: string;
}

/**
 * Inputs `PredictiveStudio.TrainModel` accepted before Prediction Units. They are refused by name when present, even
 * when empty or `asOf.Mode` is `none`: the Prediction Unit declares the decision date and the row key, and every
 * eligible row is read (a capped read is not a complete read). Kept only so a caller (or a test probe) can type a
 * payload that still sends them.
 */
export interface RetiredTrainModelInputs {
    /** Refused: the Prediction Unit declares each row''s decision date. */
    asOf?: PredictiveStudioTrainAsOf;
    /** Refused: the Prediction Unit declares each row''s decision date. */
    labelEventDates?: Record<string, string>;
    /** Refused: every eligible row is read. */
    maxRows?: number;
    /** Refused: the Prediction Unit reads its rows keyed by the row entity''s own primary key. */
    primaryKeyField?: string;
}
';
  p_OutputTypeDefinition_b00a8cc8927b := '/**
 * Output of `PredictiveStudio.TrainModel`: the run''s stored gate decision, its Training Snapshot and Evaluation
 * Protocol, and the produced model when the decision ships one.
 */
export interface PredictiveStudioTrainModelOutput {
    /** Id of the produced (Draft) `MJ: ML Models` row; absent when the gate decision ships no model (no-signal, or the existing rule kept). */
    modelId?: string;
    /** Id of the `MJ: ML Training Runs` row recording this attempt. */
    trainingRunId: string;
    /** Monotonic model version under the pipeline; absent when no model is produced. */
    version?: number;
    /**
     * JSON of the test-set scores measured once on the locked holdout (`{ "<metric>": value, … }`): the produced
     * model''s stored scores when a model exists (the member the gate ships), otherwise the trainer''s finalist scores.
     */
    holdoutMetrics?: string;
    /** True when one feature dominates the finalist''s predictions (possible target leakage); a flagged model stays Draft and needs human sign-off. */
    leakageFlagged: boolean;
    /** Lifecycle status of the produced model (`Draft`), `NoSignal` when the gate stored no-signal, or `KeptExistingRule` when it kept the existing rule. */
    status: string;
    /** The `MJ: ML Training Snapshots` row the run trained on. */
    trainingSnapshotId?: string;
    /** The `MJ: ML Evaluation Protocols` row (exact version) the run was evaluated under. */
    evaluationProtocolId?: string;
    /** That protocol row''s Version. */
    evaluationProtocolVersion?: number;
    /** The stored gate outcome. */
    gateOutcome?: ''model'' | ''keep-simple-baseline'' | ''no-signal'';
    /** The decision-table branch the stored outcome came from (for example `b:keep-simple-baseline` or `c:no-signal`). */
    gateBranch?: string;
    /** The stored reason for the outcome, in words generated from the stored comparisons. */
    gateReason?: string;
    /** The member the gate ships (the model, a simple baseline or the existing rule); absent under no-signal. */
    shipped?: string;
}
';
  p_ID_b00a8cc8927b := 'C6216E4B-9D7E-4514-AE78-B3431C9A823F';
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateRemoteOperation' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateRemoteOperation"(p_data := jsonb_build_object(
    'Description', p_Description_b00a8cc8927b,
    'InputTypeDefinition', p_InputTypeDefinition_b00a8cc8927b,
    'OutputTypeDefinition', p_OutputTypeDefinition_b00a8cc8927b,
    'ID', p_ID_b00a8cc8927b
  ));
  ELSE
    PERFORM __mj."spUpdateRemoteOperation"(p_Description := p_Description_b00a8cc8927b, p_InputTypeDefinition := p_InputTypeDefinition_b00a8cc8927b, p_OutputTypeDefinition := p_OutputTypeDefinition_b00a8cc8927b, p_ID := p_ID_b00a8cc8927b);
  END IF;
END $mj$;

-- Save MJ: Remote Operations (core SP call only)
DO $mj$
DECLARE
  p_InputTypeDefinition_c8672a37295f TEXT;
  p_ID_c8672a37295f UUID;
BEGIN
  p_InputTypeDefinition_c8672a37295f := '/**
 * Explicit resource budget for an experiment session — the bounded-autonomy
 * guardrail. Mirrors `Budget` from `@memberjunction/predictive-studio-core`.
 */
export interface PredictiveStudioBudget {
    /** Max total compute cost the session may spend. */
    MaxComputeCost?: number;
    /** Max number of training runs/iterations the session may execute. */
    MaxRuns?: number;
    /** Max wall-clock minutes the session may run. */
    MaxWallclockMinutes?: number;
}

/**
 * The strongly-typed modeling plan to execute. Mirrors `ModelingPlanSpec` from
 * `@memberjunction/predictive-studio-core` — the deterministic orchestrator runs
 * its `ProposedExperiments` as waves. Must be approved (`Approved=true`) — execution
 * is gated on user approval.
 */
export interface PredictiveStudioModelingPlanSpec {
    /** Business objective, refined from the user''s initial goal. */
    Goal: string;
    /** Precise definition of what is being predicted. */
    TargetDefinition: {
        /** Training-unit entity (e.g. "Members"). */
        EntityName: string;
        /** Label expression/column. */
        TargetVariable: string;
        /** Classification or regression. */
        ProblemType: ''classification'' | ''regression'';
        /** The deterministic success metric driving the search (e.g. AUC / F1 / Accuracy / RMSE). */
        SuccessMetric: string;
        /** Optional point-in-time assembly strategy. */
        AsOfStrategy?: { Mode: ''none'' | ''column'' | ''offset''; Column?: string; OffsetDays?: number };
    };
    /** Candidate feed-in sources proposed by the Data Scout, each with rationale. */
    CandidateSources: Array<{ Kind: ''Entity'' | ''Query'' | ''ExternalEntity'' | ''VectorSet'' | ''FeaturePipeline''; Ref: string; Why: string }>;
    /** Candidate features proposed by the Data Scout, each with rationale. */
    CandidateFeatures: Array<{ Name: string; SourceRef: string; Kind: ''numeric'' | ''categorical'' | ''embedding'' | ''llm-derived''; Why: string }>;
    /** Leakage risks identified by the Data Scout and the chosen action per field. */
    LeakageNotes: Array<{ Field: string; Risk: string; Action: ''exclude'' | ''allow'' }>;
    /** Ranked experiments proposed by the Experiment Designer (feature combos × algorithms × hyperparameters). */
    ProposedExperiments: Array<{
        Label: string;
        AlgorithmName: string;
        FeatureSet: string[];
        Hyperparameters?: Record<string, unknown>;
        Rationale: string;
        Priority: number;
    }>;
    /** Validation strategy for the search. */
    ValidationStrategy: { Strategy: ''train_test_split'' | ''kfold'' | ''holdout''; TestSize?: number; K?: number; LockedHoldoutFraction?: number };
    /** Proposed resource budget for the experiment session. */
    ProposedBudget: PredictiveStudioBudget;
    /** User approval gate — execution does not begin until this is true. */
    Approved?: boolean;
}

/** Input for `PredictiveStudio.StartExperimentSession`. */
export interface PredictiveStudioStartExperimentSessionInput {
    /** Optional id of an existing `MJ: Experiments` definition to attach the session to. When omitted, a new durable Experiment is created from the plan. */
    experimentId?: string;
    /** The approved modeling plan to execute. Must have `Approved=true`. */
    planSpec: PredictiveStudioModelingPlanSpec;
    /** Optional budget override; when omitted the plan''s `ProposedBudget` is used. */
    budget?: PredictiveStudioBudget;
    /** Optional human-readable session name (defaults to one derived from the plan goal). */
    sessionName?: string;
}
';
  p_ID_c8672a37295f := '5287084A-A59B-4CA5-AA56-E9D62C055CF3';
  IF EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = '__mj' AND p.proname = 'spUpdateRemoteOperation' AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype) THEN
    PERFORM __mj."spUpdateRemoteOperation"(p_data := jsonb_build_object(
    'InputTypeDefinition', p_InputTypeDefinition_c8672a37295f,
    'ID', p_ID_c8672a37295f
  ));
  ELSE
    PERFORM __mj."spUpdateRemoteOperation"(p_InputTypeDefinition := p_InputTypeDefinition_c8672a37295f, p_ID := p_ID_c8672a37295f);
  END IF;
END $mj$;

